use damage::*;use std::io::{self,BufRead,Write};
struct Fixture{attrs:[DamageAttributes;2],hp:[f64;2],mp:[f64;2],alive:[bool;2],buffs:[Vec<usize>;2],flags:u64,rng:rng::BattleRng,events:Vec<String>,queue:Vec<DamageCallback>}
fn bits(x:f64)->String{format!("{:016x}",x.to_bits())}
impl Fixture{
 fn bit(&self,n:u32)->bool{self.flags&(1<<n)!=0}
 fn event(&mut self,kind:&str,args:Vec<String>){let lists=self.buffs.iter().map(|l|format!("[{}]",l.iter().map(|v|v.to_string()).collect::<Vec<_>>().join(","))).collect::<Vec<_>>().join(",");self.events.push(format!("{{\"kind\":\"{}\",\"args\":[{}],\"state\":{{\"hp\":[\"{}\",\"{}\"],\"mp\":[\"{}\",\"{}\"],\"alive\":[{},{}],\"buffs\":[{}],\"rng\":\"{}\",\"queued\":{}}}}}",kind,args.iter().map(|s|format!("\"{}\"",s)).collect::<Vec<_>>().join(","),bits(self.hp[0]),bits(self.hp[1]),bits(self.mp[0]),bits(self.mp[1]),self.alive[0],self.alive[1],lists,bits(self.rng.snapshot().state),self.queue.len()));}
 fn ev(&mut self,kind:&str){self.event(kind,vec![])}
}
impl TakeDamageHooks for Fixture{
 type Extra=();
 fn attrs(&self,u:usize)->&DamageAttributes{&self.attrs[u]}fn camp(&self,u:usize)->f64{if u==0{1.0}else{-1.0}}fn hp(&self,u:usize)->f64{self.hp[u]}fn mp(&self,u:usize)->f64{self.mp[u]}fn player_camp(&self)->f64{1.0}fn enemy_camp(&self)->f64{-1.0}fn debug_attack_ratio(&self)->f64{1.1}
 fn is_field_npc(&self,_:usize)->bool{self.bit(3)}fn can_critical_special(&self,_:usize)->bool{self.bit(4)}fn invulnerable(&self,_:usize)->bool{self.bit(7)}fn uncontrollable(&self,_:usize)->bool{self.bit(11)}fn multi_damaged_state(&self,_:usize)->bool{self.bit(8)}fn is_birth(&self,_:usize)->bool{self.bit(9)}fn is_fall(&self,_:usize)->bool{self.bit(10)}fn thump_condition(&self,_:usize)->Option<f64>{Some(8.0)}fn thump_resistance(&self,_:usize)->f64{1.0}fn mp_gain_rate(&self,_:usize)->f64{100.0}fn config_mode(&self)->&str{if self.bit(21){"rt_pvp"}else{"stage"}}fn actor(&self,u:usize)->Option<usize>{self.bit(20).then_some(u)}fn position_x(&self,u:usize)->f64{if u==0{5.0}else{10.0}}fn skill_no_shield_coefficient(&self,_:usize)->Option<f64>{if self.bit(14){Some(0.3)}else{None}}
 fn buff_count(&self,u:usize)->usize{self.buffs[u].len()}fn buff_at(&self,u:usize,i:usize)->usize{self.buffs[u][i]}fn buff_make_damage_value(&self,b:usize)->f64{b as f64}fn buff_damaged_value(&self,b:usize)->f64{b as f64*0.5}fn buff_is_shield(&self,b:usize)->bool{b==3||b==4}fn rage(&self,u:usize)->Option<usize>{self.bit(if u==0{5}else{6}).then_some(u)}
 fn is_pet(&mut self,u:usize)->DamageResult<bool>{self.event("is_pet",vec![u.to_string()]);Ok(self.bit(if u==0{1}else{0}))}fn is_alive(&mut self,u:usize)->DamageResult<bool>{self.event("is_alive",vec![u.to_string()]);Ok(self.alive[u])}
 fn prior_make_damage(&mut self,b:usize,x:f64,_:usize,_:Option<usize>,_:&str)->DamageResult<f64>{self.event("prior",vec![b.to_string(),bits(x)]);Ok(x+1.0)}
 fn post_switch_type(&mut self,b:usize,x:f64,_:usize,_:Option<usize>,_:&str,c:&mut DamageContext)->DamageResult<()>{self.event("post",vec![b.to_string(),bits(x)]);if self.bit(18){c.defence_ignore_coefficient=Some(0.25)}if self.bit(19){c.immunity_ignore_coefficient=Some(0.2)}Ok(())}
 fn probability_hooks(&mut self,p:f64,_:Option<usize>,_:usize,_:Option<usize>,_:&str)->DamageResult<f64>{self.event("probability",vec![bits(p)]);Ok(p)}fn fix_probability(&mut self,p:f64,camp:f64)->DamageResult<f64>{self.event("fix_probability",vec![bits(p),bits(camp)]);Ok(p)}fn random(&mut self)->DamageResult<f64>{self.ev("random");Ok(self.rng.next_f64())}fn critical_coefficient(&mut self,a:usize,d:usize)->DamageResult<f64>{self.ev("crit_coefficient");Ok(critical_coefficient(self.attrs[a].critp,self.attrs[d].critd,self.attrs[a].critplu))}
 fn after_immunity(&mut self,_:usize,x:f64,s:f64)->DamageResult<f64>{self.event("immunity",vec![bits(x),bits(s)]);Ok(lost_after_immunity(x,s))}fn level_suppress_coefficient(&self,_:usize)->f64{if self.bit(22){0.1}else{0.0}}fn level_suppress_offset(&self,_:usize)->f64{0.0}fn level_suppress_a_to_b(&mut self,_:usize,_:usize,_:f64)->DamageResult<f64>{self.ev("level_suppress");Ok(0.2)}fn tag_damage(&mut self,_:usize,_:usize,x:f64)->DamageResult<f64>{self.event("tag",vec![bits(x)]);Ok(x)}
 fn magic_dodge(&mut self,_:usize,_:usize,_:Option<usize>)->DamageResult<bool>{self.ev("magic_dodge");if !self.bit(17){return Ok(false)}let p=dodge_probability(10.0,0.0);Ok(self.random()?<p)}
 fn make_damage(&mut self,b:usize,x:f64,_:usize,_:Option<usize>,_:bool,_:&str,c:&mut DamageContext)->DamageResult<f64>{self.event("make",vec![b.to_string(),bits(x),c.defence_ignore_damage_coefficient.map(bits).unwrap_or_else(||"u".into()),c.immunity_ignore_damage_coefficient.map(bits).unwrap_or_else(||"u".into())]);Ok(x+2.0)}fn rage_make_damage(&mut self,_:usize,_:usize,x:f64,_:usize,_:Option<usize>,_:bool)->DamageResult<f64>{self.event("rage_make",vec![bits(x)]);Ok(x*1.1)}
 fn on_damaged(&mut self,b:usize,x:f64,_:&str,_:usize,_:bool,_:bool,_:Option<usize>)->DamageResult<f64>{self.event("damaged",vec![b.to_string(),bits(x)]);if self.bit(15){self.buffs[1].retain(|id|*id!=b)}Ok(x-0.5)}fn warn_removed_buff(&mut self)->DamageResult<()>{self.ev("warn");Ok(())}fn local_bot(&self)->bool{self.bit(13)}fn on_damage_shield(&mut self,b:usize,x:f64,_:&str,_:usize,_:bool,_:bool,_:Option<usize>)->DamageResult<f64>{self.event("shield",vec![b.to_string(),bits(x)]);if self.bit(16){self.buffs[1].retain(|id|*id!=b)}Ok(x*0.5)}
 fn rage_take_damage(&mut self,_:usize,_:usize,x:f64,_:&str,_:usize,_:bool,_:bool,_:Option<usize>)->DamageResult<f64>{self.event("rage_take",vec![bits(x)]);Ok(x*0.9)}fn final_damaged(&mut self,b:usize,x:f64,_:&str,_:usize,_:bool,_:Option<usize>)->DamageResult<f64>{self.event("final",vec![b.to_string(),bits(x)]);Ok(x-0.25)}fn rage_take_damage_final(&mut self,_:usize,_:usize,x:f64)->DamageResult<f64>{self.event("rage_final",vec![bits(x)]);Ok(x*0.95)}
 fn summon_hero(&mut self,u:usize)->DamageResult<usize>{self.ev("summon");Ok(u)}fn success_make_damage(&mut self,_:usize,_:usize,x:f64,_:())->DamageResult<()>{self.event("success",vec![bits(x)]);Ok(())}fn success_buff_damage(&mut self,b:usize,x:f64,_:usize,_:&str,_:Option<usize>,_:bool,_:())->DamageResult<()>{self.event("success_buff",vec![b.to_string(),bits(x)]);Ok(())}
 fn record_damage(&mut self,_:usize,x:f64,_:usize,_:Option<usize>)->DamageResult<()>{self.event("record_damage",vec![bits(x)]);Ok(())}fn record_real_bear_damage(&mut self,_:usize,x:f64,_:usize)->DamageResult<()>{self.event("record_real",vec![bits(x)]);Ok(())}fn record_bear_damage(&mut self,_:usize,x:f64)->DamageResult<()>{self.event("record_bear",vec![bits(x)]);Ok(())}
 fn set_hp(&mut self,u:usize,x:f64)->DamageResult<()>{self.event("set_hp",vec![bits(x)]);self.hp[u]=js_max(0.0,x);Ok(())}fn die(&mut self,u:usize,_:usize)->DamageResult<()>{self.ev("die");self.alive[u]=false;Ok(())}fn fix_thump_condition(&mut self,x:f64,camp:f64)->DamageResult<f64>{self.event("fix_thump",vec![bits(x),bits(camp)]);Ok(x)}fn multi_damaged(&mut self,_:usize)->DamageResult<()>{self.ev("multi");Ok(())}fn check_resistance(&mut self,_:usize,_:usize)->DamageResult<bool>{self.ev("resistance");Ok(self.bit(12))}fn thump(&mut self,_:usize)->DamageResult<()>{self.ev("thump");Ok(())}fn transfer_mp_target(&mut self,u:usize)->DamageResult<usize>{self.ev("transfer_mp");Ok(u)}fn fix_gain_mp(&mut self,x:f64,_:MpSource,camp:f64)->DamageResult<f64>{self.event("fix_mp",vec![bits(x),bits(camp)]);Ok(x)}fn set_mp(&mut self,u:usize,x:f64,_:usize)->DamageResult<()>{self.event("set_mp",vec![bits(x)]);self.mp[u]=x;Ok(())}fn unfreeze_actor(&mut self,_:usize,_:bool)->DamageResult<()>{self.ev("unfreeze_actor");Ok(())}
 fn enqueue(&mut self,c:DamageCallback)->DamageResult<()>{self.ev("queue");self.queue.push(c);Ok(())}
 fn popup(&mut self,p:DamagePopup)->DamageResult<()>{let actor=|a:Option<usize>|a.map(|id|format!("actor:{id}")).unwrap_or_else(||"u".into());let args=match p{DamagePopup::Text{text,color,actor:a}=>vec!["popUpBattleNum".into(),text.into(),if color==PopupColor::Red{"red".into()}else{"blue".into()},actor(a),"null".into(),"text".into()],DamagePopup::Number{label,color,actor:a,critical,direction,scale,number}=>vec!["popUpBattleNum".into(),label.into(),color.into(),actor(Some(a)),critical.to_string(),"null".into(),bits(direction),bits(scale),bits(number)]};self.event("popup",args);Ok(())}
 fn log_take_damage(&mut self,_:usize,x:f64,kind:&str,field:&str,_:usize,ratio:f64)->DamageResult<()>{self.event("log",vec![bits(x),kind.into(),field.into(),bits(ratio)]);Ok(())}
}
const KINDS:[&str;8]=["AD","AP","Holy","HolyCanCrit","Special","PET","NoMIMUAP","Unknown"];
fn main()->io::Result<()>{let stdin=io::stdin();let mut out=io::BufWriter::new(io::stdout().lock());for line in stdin.lock().lines(){let line=line?;let mut words=line.split_whitespace();let flags=words.next().unwrap().parse().unwrap();let kind=words.next().unwrap().parse::<usize>().unwrap();let field=words.next().unwrap().parse::<usize>().unwrap();let na=words.next().unwrap().parse::<usize>().unwrap();let nd=words.next().unwrap().parse::<usize>().unwrap();let numbers:Vec<f64>=words.map(|x|f64::from_bits(u64::from_str_radix(x,16).unwrap())).collect();assert_eq!(numbers.len(),33);
 let attrs=|n:&[f64]|DamageAttributes{atk:n[0],arm:n[1],crit:n[2],dcrit:n[3],dpimu:n[4],pimu:n[5],dmimu:n[6],mimu:n[7],himu:n[8],critp:n[9],critd:n[10],critplu:n[11],hp:n[12]};let mut rng=rng::BattleRng::default();rng.seed(numbers[32]);let mut h=Fixture{attrs:[attrs(&numbers[..13]),attrs(&numbers[13..26])],hp:[numbers[28],numbers[29]],mp:[numbers[30],numbers[31]],alive:[true,flags&(1<<2)!=0],buffs:[(0..na).collect(),(2..2+nd).collect()],flags,rng,events:vec![],queue:vec![]};
 h.ev("enter");let result=take_damage(&mut h,1,numbers[26],KINDS[kind],Some(["hp","mp",""][field]),Some(0),Some(numbers[27]),Some(0),()).unwrap();h.ev("after_damage");while !h.queue.is_empty(){let c=h.queue.remove(0);execute_damage_callback(&mut h,c).unwrap();}h.ev("after_callbacks");writeln!(out,"{{\"lost\":\"{}\",\"critical\":{},\"events\":[{}]}}",bits(result.lost),result.critical.map(|x|x.to_string()).unwrap_or_else(||"\"u\"".into()),h.events.join(","))?;
 }out.flush()}
